import{_ as o,o as t,c as s,a2 as a}from"./chunks/framework.BS0bAV7E.js";const _=JSON.parse('{"title":"The Chinese console layer","description":"","frontmatter":{},"headers":[],"relativePath":"arch/chinese-layer.md","filePath":"arch/chinese-layer.md"}'),c={name:"arch/chinese-layer.md"};function r(n,e,i,l,d,h){return t(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="the-chinese-console-layer" tabindex="-1">The Chinese console layer <a class="header-anchor" href="#the-chinese-console-layer" aria-label="Permalink to &quot;The Chinese console layer&quot;">​</a></h1><p><code>chinese/</code> renders CJK user content while the system&#39;s own strings stay ASCII:</p><h2 id="pieces" tabindex="-1">Pieces <a class="header-anchor" href="#pieces" aria-label="Permalink to &quot;Pieces&quot;">​</a></h2><ul><li><code>chinese_font_data.c</code> - the 16x16 bitmap glyphs</li><li><code>encoding.c</code> - gb2312 / utf-8 / ascii codecs (round-trip tested)</li><li><code>console_cn.c</code> - CJK console rows on the framebuffer</li><li><code>render_cn.c</code> - glyph raster pipeline</li><li><code>pinyin_data.c</code> + the IME - syllable resolution, interactive line</li><li><code>tui_cn_*.c</code> - CN hardware/net/sysinfo TUI apps</li></ul><h2 id="why-both-worlds-work" tabindex="-1">Why both worlds work <a class="header-anchor" href="#why-both-worlds-work" aria-label="Permalink to &quot;Why both worlds work&quot;">​</a></h2><p>The ASCII contract is about <em>system</em> strings (prompts, command names, help, boot messages) - hardware-terminal compatibility. User content (filenames, file bodies, editor buffers) flows through the codecs and renders on the CJK font when the layer is active. With <code>CONFIG_CHINESE=n</code> the console routes to the ASCII equivalents in <code>screen_console</code> - real code, both paths, one contract.</p><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><p><code>chinesetest</code> (full regression), <code>encoding-test</code> (codec round-trip), <code>font-test</code> (mixed-row render), <code>ime-test</code> (syllable resolution).</p>',8)])])}const m=o(c,[["render",r]]);export{_ as __pageData,m as default};
